package com.acme.dispute.controller; import com.acme.dispute.entity.Dispute; import com.acme.dispute.service.DisputeService; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/disputes") public class DisputeController { private final DisputeService service; public DisputeController(DisputeService s){service=s;} @GetMapping("/{id}") public Dispute get(@PathVariable Long id){ return service.find(id).orElseThrow(); } @GetMapping("/search") public List<Map<String,Object>> search(@RequestParam String email){ return service.searchByEmail(email);} }